window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-024ebff6c2f1cf4b"]={"versions": [{"id": "FIG-024ebff6c2f1cf4b", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Paketformat- bzw. Bitfeld-Layout-Diagramm zur Darstellung der Struktur einer AUTOSAR Service Discovery (SD) Nachricht im Kontext des SOME/IP-SD-Protokolls auf Netzwerk- und Service-Layer-Ebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Format umfasst eine 32-Bit-Rasterung (Bit 0 bis 31). Die Entitäten gliedern sich in:</p>\n<ul class=\"fig-list\"><li>Header-Bereich (SOME/IP-Header-Bestandteile):\n<ul class=\"fig-list\"><li>Request ID (Client ID / Session ID) [32 bit]\n</li><li>Protocol Version [8 bit] (festgelegt auf =0x01)\n</li><li>Interface Version [8 bit] (festgelegt auf =0x01)\n</li><li>Message Type [8 bit] (festgelegt auf =0x02)\n</li><li>Return Code [8 bit] (festgelegt auf =0x00)\n</li></ul>\n</li><li>Service-Discovery-spezifischer Payload-Header:\n<ul class=\"fig-list\"><li>Flags [8 bit]\n</li><li>Reserved [24 bit]\n</li></ul>\n</li><li>Dynamische Nutzdatenblöcke mit Längenfeldern:\n<ul class=\"fig-list\"><li>Length of Entries Array [32 bit]\n</li><li>Entries Array (variable Länge, referenziert durch „Covered by Length“)\n</li><li>Length of Options Array [32 bit]\n</li><li>Options Array (variable Länge, referenziert durch „Covered by Length“)\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Serialisierungs- und Nachrichtenlayout ohne Ablaufsequenz. Die Übertragung erfolgt sequentiell von Bit 0 bis 31 bzw. Byte für Byte. Zunächst werden die festen Header- und Steuerfelder ausgewertet, gefolgt vom Einlesen der dynamischen Feldelemente: Die Längenfelder bestimmen jeweils die Bytelänge der direkt nachfolgenden Arrays (Entries Array bzw. Options Array).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Nachrichtenlayout gemäß [SWS_SD_00030], an das alle Service Discovery Messages gebunden sind. Implementierungen müssen feste Konstanten einhalten (Protocol Version 0x01, Interface Version 0x01, Message Type 0x02, Return Code 0x00), das 24-Bit-Reserved-Feld beachten sowie die 32-Bit-Längenangaben strikt zur Dekodierung der variablen Datenarrays (Entries und Options) verwenden.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-c5edf902e640ee97", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Paketformat- bzw. Bitfeld-Layout-Diagramm zur Darstellung der Struktur einer AUTOSAR Service Discovery (SD) Nachricht im Kontext des SOME/IP-SD-Protokolls auf Netzwerk- und Service-Layer-Ebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Format umfasst eine 32-Bit-Rasterung (Bit 0 bis 31). Die Entitäten gliedern sich in:</p>\n<ul class=\"fig-list\"><li>Header-Bereich (SOME/IP-Header-Bestandteile):\n<ul class=\"fig-list\"><li>Request ID (Client ID / Session ID) [32 bit]\n</li><li>Protocol Version [8 bit] (festgelegt auf =0x01)\n</li><li>Interface Version [8 bit] (festgelegt auf =0x01)\n</li><li>Message Type [8 bit] (festgelegt auf =0x02)\n</li><li>Return Code [8 bit] (festgelegt auf =0x00)\n</li></ul>\n</li><li>Service-Discovery-spezifischer Payload-Header:\n<ul class=\"fig-list\"><li>Flags [8 bit]\n</li><li>Reserved [24 bit]\n</li></ul>\n</li><li>Dynamische Nutzdatenblöcke mit Längenfeldern:\n<ul class=\"fig-list\"><li>Length of Entries Array [32 bit]\n</li><li>Entries Array (variable Länge, referenziert durch „Covered by Length“)\n</li><li>Length of Options Array [32 bit]\n</li><li>Options Array (variable Länge, referenziert durch „Covered by Length“)\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Serialisierungs- und Nachrichtenlayout ohne Ablaufsequenz. Die Übertragung erfolgt sequentiell von Bit 0 bis 31 bzw. Byte für Byte. Zunächst werden die festen Header- und Steuerfelder ausgewertet, gefolgt vom Einlesen der dynamischen Feldelemente: Die Längenfelder bestimmen jeweils die Bytelänge der direkt nachfolgenden Arrays (Entries Array bzw. Options Array).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Nachrichtenlayout gemäß [SWS_SD_00030], an das alle Service Discovery Messages gebunden sind. Implementierungen müssen feste Konstanten einhalten (Protocol Version 0x01, Interface Version 0x01, Message Type 0x02, Return Code 0x00), das 24-Bit-Reserved-Feld beachten sowie die 32-Bit-Längenangaben strikt zur Dekodierung der variablen Datenarrays (Entries und Options) verwenden.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-33029c9ce91b486b", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Paketformat- bzw. Bitfeld-Layout-Diagramm zur Darstellung der Struktur einer AUTOSAR Service Discovery (SD) Nachricht im Kontext des SOME/IP-SD-Protokolls auf Netzwerk- und Service-Layer-Ebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Format umfasst eine 32-Bit-Rasterung (Bit 0 bis 31). Die Entitäten gliedern sich in:</p>\n<ul class=\"fig-list\"><li>Header-Bereich (SOME/IP-Header-Bestandteile):\n<ul class=\"fig-list\"><li>Request ID (Client ID / Session ID) [32 bit]\n</li><li>Protocol Version [8 bit] (festgelegt auf =0x01)\n</li><li>Interface Version [8 bit] (festgelegt auf =0x01)\n</li><li>Message Type [8 bit] (festgelegt auf =0x02)\n</li><li>Return Code [8 bit] (festgelegt auf =0x00)\n</li></ul>\n</li><li>Service-Discovery-spezifischer Payload-Header:\n<ul class=\"fig-list\"><li>Flags [8 bit]\n</li><li>Reserved [24 bit]\n</li></ul>\n</li><li>Dynamische Nutzdatenblöcke mit Längenfeldern:\n<ul class=\"fig-list\"><li>Length of Entries Array [32 bit]\n</li><li>Entries Array (variable Länge, referenziert durch „Covered by Length“)\n</li><li>Length of Options Array [32 bit]\n</li><li>Options Array (variable Länge, referenziert durch „Covered by Length“)\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Serialisierungs- und Nachrichtenlayout ohne Ablaufsequenz. Die Übertragung erfolgt sequentiell von Bit 0 bis 31 bzw. Byte für Byte. Zunächst werden die festen Header- und Steuerfelder ausgewertet, gefolgt vom Einlesen der dynamischen Feldelemente: Die Längenfelder bestimmen jeweils die Bytelänge der direkt nachfolgenden Arrays (Entries Array bzw. Options Array).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Nachrichtenlayout gemäß [SWS_SD_00030], an das alle Service Discovery Messages gebunden sind. Implementierungen müssen feste Konstanten einhalten (Protocol Version 0x01, Interface Version 0x01, Message Type 0x02, Return Code 0x00), das 24-Bit-Reserved-Feld beachten sowie die 32-Bit-Längenangaben strikt zur Dekodierung der variablen Datenarrays (Entries und Options) verwenden.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-024ebff6c2f1cf4b", "to": "FIG-c5edf902e640ee97", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-c5edf902e640ee97", "to": "FIG-33029c9ce91b486b", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
